def solve(gi):
    h,w=len(gi),len(gi[0])
    br=gi[h-1]
    segs=[]; i=0
    while i<w:
        if br[i]!=0:
            j=i
            while j<w and br[j]!=0: j+=1
            segs.append(br[i:j]); i=j
        else: i+=1
    out=[row[:] for row in gi]
    for r in range(h-1):
        row=gi[r]
        marks=[]
        for c,v in enumerate(row):
            if v==0: continue
            left = c==0 or row[c-1]==0
            right = c==w-1 or row[c+1]==0
            # isolated if both sides are zero
            if left and right:
                marks.append((c,v))
        for c,v in marks:
            src=None
            for s in segs:
                if v in s: src=s; break
            if src is None:
                continue
            pos=src.index(v)
            a=c-pos
            for k in range(len(src)):
                cc=a+k
                if 0<=cc<w:
                    out[r][cc]=src[k]
    return out
