def solve(inp):
    h=len(inp); w=len(inp[0])
    # gather segments of consecutive nonzero cells in each row
    segs=[]
    for i,row in enumerate(inp):
        j=0
        while j<w:
            if row[j]!=0:
                s=[row[j]]; jj=j+1
                while jj<w and row[jj]!=0: s.append(row[jj]); jj+=1
                segs.append((i,j,len(s),tuple(s))); break
            else: j+=1
    g=[row[:] for row in inp]
    for i,row in enumerate(inp):
        for c,x in enumerate(row):
            if x==0: continue
            seg=None
            for si,s in enumerate(segs):
                if s[1]==c and s[0]==i and True: seg=s
            if seg is None: continue
            _,c0,L,sv=list(seg)
            idx=list(sv).index(x) if False else sv.index(x)
            # fill entire segment region with cyclic shift so that mark lands at correct position: fill cols c-L+idx .. c+L-1-idx? 
            # observed: row fills from col0? demo1 row5: mark at col2 idx3, fills cols 0..4 -> shifted so seg[3] at col2
            start=c-idx
            for k in range(max(0,start),min(w,L)+start):
                g[i][k]=sv[k-start]
    return g
