def solve(inp):
    h=len(inp); w=len(inp[0])
    seq=[]
    for i,row in enumerate(inp):
        for x in row:
            if x: seq.append(x)
    # global seq = dedupe preserving order of first appearance? demo1 seq [2,3,5,1,6,4] bottom; marks 2(idx0),1(idx3),4(idx5) all match. demo2 seq=[1,2,4,3,5,7,8,6]: marks 2,8,1,4,6,4 all present.
    g=[row[:] for row in inp]
    for i,row in enumerate(inp):
        for j,x in enumerate(row):
            if x==0 or not(0<j<len(seq)-1): continue  # only isolated interior marks? test check later
            idx=list(dict.fromkeys(seq)).index(x)
            start=j-idx
            L=len(list(dict.fromkeys(seq)))
            for k in range(max(0,start),min(w,start+L)):
