def solve(inp):
    h=len(inp); w=len(inp[0]); g=[r[:] for r in inp]
    segs=[]
    for i in range(h):
        j=0
        while j<w:
            if inp[i][j]!=0:
                k=j
                while k<w and inp[i][k]!=0: k+=1
                if k-j>1: segs.append((i,j,k,tuple(inp[i[j:k+1]])))
                j=k
            else: j+=1
    marks=[(i,j) for i in range(h) for j in range(w) if inp[i][j]!=0 and
           all(not(seg[0]==i and seg[1]<=j<=seg[2]) or False for _ in []) ]
    # isolated mark: cell not part of any length>=2 segment
    cells={(a,b) for s in segs for b in range(s[1],s[2]+1)}
    out=[r[:] for r in inp]
    for i in range(h):
        for j in range(w):
            if inp[i][j]!=0 and (i,j) not in cells:
                for (sa,sb,se,sv) in segs:
                    if sv.index(inp[i][j])== -1: continue
                    if len(sv)<2: continue
                    x0=sv.index(inp[i][j])
                    start=j-x0
                    for c in range(start,start+len(sv)):
                        if 0<=c<w: out[i][c]=sv[c-start]
    return out
